// Schede EmS – generato da tools/build_ems.py, non modificare a mano
DATA.ems = {"fonte":"MSC.1/Circ.1588/Rev.4 (14 July 2026), Revised EmS Guide, amendment 43-26","sched":{"F-A":{"t":"GENERAL FIRE SCHEDULE","r":[{"l":[["General comments",""]],"p":["In a fire, exposed cargoes may explode or their containment may rupture.","Fight fire from a protected position from as far away as possible."]},{"l":[["Cargo on fire on deck","Packages"],["Cargo on fire on deck","Cargo transport units"]],"p":["Create water spray from as many hoses as possible."]},{"l":[["Cargo on fire under deck",""]],"p":["Stop ventilation and close hatches.","Use cargo space fixed fire-extinguishing system. If this is not available, create water spray using copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in fire. Otherwise, keep cool using water."]}],"pag":21,"sc":[{"c":"","un":["1381","2447"],"p":["After extinguishing the fire, treat immediately as for spillage (see relevant EmS SPILLAGE SCHEDULE)."]}]},"F-B":{"t":"EXPLOSIVE SUBSTANCES AND ARTICLES","r":[{"l":[["General comments",""]],"p":["In a fire, exposed cargoes may explode or their containment may rupture.","Fight fire from a protected position from as far away as possible.","All crew members should be made aware of the explosion hazard and instructed to take appropriate action.","SUDDEN OR SHORT-TERM EVENTS (e.g. EXPLOSIONS) MAY ENDANGER THE SAFETY OF THE SHIP."]},{"l":[["Cargo on fire on deck","Packages"],["Cargo on fire on deck","Cargo transport units"]],"p":["Use copious quantities of water from as many hoses as possible.","Cargo will explode or burn fiercely. Extinguishing may not be possible."]},{"l":[["Cargo on fire under deck",""]],"p":["Cargo will explode or burn fiercely. Extinguishing will not be possible.","Stop ventilation and close hatches.","Use cargo space fixed fire-extinguishing system. If this is not available, create water spray using copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["Do not move packages that have been exposed to heat.","If practicable, remove or jettison packages which are likely to be involved in the fire. If the packages are not directly involved in the fire, efforts should be concentrated on preventing the fire from reaching the cargo. This is done by keeping the packages wet by using water jets from as far away as practicable to drive the fire away. If the fire reaches the cargo, the firefighters should withdraw to a safe area and continue to fight the fire.","Where practicable, articles having been exposed to the fire should be kept separated from unexposed articles. They should be kept wet and monitored from a safe distance."]}],"pag":22,"sc":[{"c":"","un":["0018","0019","0020","0021","0301"],"p":["Ammunition producing tear or toxic gas. The crew should be aware of the hazard. After explosion, only self-contained breathing apparatus will protect efficiently. Consult SPILLAGE SCHEDULE S-Z."]},{"c":"","un":["0248","0249"],"p":["These water-activated devices will become more liable to explosion on contact with water."]},{"c":"","un":["3268"],"p":["SAFETY DEVICES, electrically initiated, could be subject to self-sustaining decomposition if heated. The temperature could reach 500°C, producing gas. This process may lead to an explosion of the cargo even after the exposure to heat has ended."]}]},"F-C":{"t":"NON-FLAMMABLE GASES","r":[{"l":[["General comments",""]],"p":["Gases in closed tanks exposed to heat may explode suddenly in or after a fire situation by a boiling liquid – expanding vapour explosion (BLEVE). Heated or ruptured cylinders may rocket.","Gases listed under this schedule are non-flammable. However, some gases will support combustion though not flammable itself.","Fire may produce leakages. Most gases allocated to this schedule are hazardous to health. Some are corrosive. Create water spray.","Identify the source of the fire and take appropriate action."]},{"l":[["Cargo on fire on deck","Packages"],["Cargo on fire on deck","Cargo transport units"]],"p":["Use copious quantities of water from as many hoses as possible."]},{"l":[["Cargo on fire under deck",""]],"p":["Use fixed fire-extinguishing system."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in the fire. Otherwise, cool for several hours using water.","Heated or ruptured cylinders may rocket."]}],"pag":24,"sc":[{"c":"","un":["1003","1070","1072","1073","2201","3156","3157","3513","3515","3518"],"p":["Although these cargoes are non-flammable, they will intensify the fire."]}]},"F-D":{"t":"FLAMMABLE GASES","r":[{"l":[["General comments",""]],"p":["Gases in closed tanks exposed to heat may explode suddenly in or after a fire situation by a boiling liquid – expanding vapour explosion (BLEVE).","Crew members should be aware of the explosion hazard and take appropriate action.","Keep tanks cool with copious quantities of water.","Fight fire from a protected position from as far away as possible.","Extinguishing a burning gas leak may lead to the formation of an explosive atmosphere.","Flames may be invisible."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["Create water spray from as many hoses as possible.","Do not try to extinguish a gas flame."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Cool burning transport units and nearby cargo exposed to the fire with copious quantities of water.","Do not try to extinguish a gas flame."]},{"l":[["Cargo on fire under deck",""]],"p":["Stop ventilation and close hatches.","Use cargo space fixed fire-extinguishing system. If this is not available, create water spray using copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in the fire. Otherwise, keep cool for several hours using water."]}],"pag":25,"sc":[{"c":"","un":["1038","1075","1965","1966","1972","3138","3160","3309","3312"],"p":["SUDDEN OR SHORT-TERM EVENTS (e.g. EXPLOSIONS) MAY ENDANGER THE SAFETY OF THE SHIP."]},{"c":"","un":["1001","3374"],"p":["Acetylene is a gas which is particularly dangerous due to its potential to explode. Rough handling or local heating may lead to delayed explosion. Keep cool for several hours using water. Do not move receptacles. All cylinders that have been subjected to rough handling or to local heating should be jettisoned."]},{"c":"","un":["3501","3504","3505"],"p":["A flammable liquid, paste or powder may be expelled if the package is ruptured.","Also consult FIRE SCHEDULE F-E."]}]},"F-E":{"t":"NON-WATER-REACTIVE FLAMMABLE LIQUIDS","r":[{"l":[["General comments",""]],"p":["Cargoes in tanks exposed to heat may explode suddenly in or after a fire situation by a boiling liquid – expanding vapour explosion (BLEVE). Keep tanks cool with copious quantities of water.","Fight fire from a protected position from as far away as possible.","Stop leakage or close open valve if practicable.","Flames may be invisible."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["Create water spray from as many hoses as possible."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Cool burning transport units and nearby cargo exposed to the fire with copious quantities of water."]},{"l":[["Cargo on fire under deck",""]],"p":["Stop ventilation and close hatches.","Use cargo space fixed fire-extinguishing system. If this is not available, create water spray using copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in the fire. Otherwise, keep cool for several hours using water."]}],"pag":27,"sc":[{"c":"","un":["1162","1250","1298","1717","2985"],"p":["Cargoes will create hydrochloric acid in contact with water: stay away from effluent."]}]},"F-F":{"t":"TEMPERATURE-CONTROLLED SELF-REACTIVES AND ORGANIC PEROXIDES","r":[{"l":[["General comments",""]],"p":["Exposed cargoes may decompose violently.","Crew members should be aware of the explosion hazard and take appropriate action.","Fight fire from a protected position from as far away as possible.","Switch off electrical power supplies only during firefighting.","Check temperature readings if possible. Measures have to be taken to alert the crew when the temperature of the cargo increases.","In case of a temperature increase or smoke evolution, follow the relevant instructions.","Contact the manufacturer (consignor) of the cargo as soon as possible."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["Not applicable."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Cool burning transport units and nearby cargo exposed to the fire with copious quantities of water.","After the fire has been extinguished, do not open the unit until well after smoke evolution has ceased. If possible, restore cooling. Keep under surveillance."]},{"l":[["Cargo on fire under deck",""]],"p":["Not applicable. According to the IMDG Code, under deck stowage is not allowed. Radio for expert ADVICE."]},{"l":[["Cargo exposed to fire","Cargo transport units with IBCs, packages"]],"p":["Cool units exposed to fire with water.","After the fire has been extinguished, check and restore cooling. Keep under surveillance. Check temperature frequently.","In case of temperature increase or smoke evolution, follow the relevant instructions."]},{"l":[["Cargo exposed to fire","Tanks"]],"p":["Keep personnel away from tanks as liquid may be ejected from relief arrangements.","Cool units exposed to fire with copious quantities of water.","After the fire has been extinguished, check and restore cooling. Keep under surveillance.","After the fire has been extinguished, water spray should be continued to cool down the outer parts of the tanks. Check refrigeration unit, keep tanks under surveillance. Check temperature frequently."]},{"l":[["Temperature increase","Cargo transport units with IBCs, packages"]],"p":["If the control temperature is exceeded, the refrigeration unit has to be inspected (consult manual) and repaired. If not possible and/or temperature control cannot be restored, contact the manufacturer of the cargo.","If the emergency temperature is reached but the refrigeration unit is operating correctly, contact the manufacturer of the cargo and consider disposal of packagings. Keep firefighting team on stand-by.","If the emergency temperature is reached due to cooling unit failure, contact the manufacturer of the cargo. When emergency temperature is reached, 12 hours are left for repairing the cooling unit and/or disposal of packaging. After that time, keep a safe distance and prepare for firefighting."]},{"l":[["Temperature increase","Tanks"]],"p":["If the control temperature is exceeded, the refrigeration unit has to be inspected (consult manual) and repaired. If not possible and/or temperature control cannot be restored, contact manufacturer of the cargo.","If the emergency temperature is reached but the refrigeration unit is operating correctly, contact the manufacturer of the cargo. Keep at a safe distance and consider emptying of tank overboard via bottom outlet using a flexible hose.","If the emergency temperature is reached due to failure of the cooling unit, repairs may be undertaken as long as the temperature has not exceeded the emergency temperature by more than 5°C. After that, consider emptying the tank using a flexible hose attached to the bottom opening of the tank if provided."]},{"l":[["Smoke evolution","Cargo transport units with IBCs, packages"]],"p":["Keep firefighting team on stand-by.","The freight container should not be approached. When smoke evolution increases, keep safe distance and prepare for firefighting. After smoke has ceased, check refrigeration system. Follow guidelines for temperature increase.","Keep under surveillance, as new smoke evolution might take place."]},{"l":[["Smoke evolution","Tanks"]],"p":["Keep personnel away from the tank, as liquid may be ejected from relief arrangements.","Cool unit exposed to fire with water. Use water spray from a protected position.","In case smoke or pressure-relief venting is moderate and temperature is below the emergency temperature, consider emptying the tank overboard via bottom outlet, using a flexible hose.","Even when smoke evolution or pressure-relief venting has ceased, water spray should be continued for some hours and the tank should be kept under surveillance, as new smoke evolution might take place."]}],"pag":28,"sc":[]},"F-G":{"t":"WATER-REACTIVE SUBSTANCES","r":[{"l":[["General comments",""]],"p":["In a fire, exposed cargoes may explode or their containment may rupture.","Liquid material leaking from ruptured receptacles may be ignited and spread the fire.","Cargoes in tanks exposed to heat may explode suddenly in or after a fire situation by a boiling liquid – expanding vapour explosion (BLEVE).","Fight fire from a protected position from as far away as possible.","Use of copious quantities of water at once is recommended to cool down the heat radiation and to cool down heated cargo nearby.","Water in direct contact with the material will start or intensify burning of that material. Only in locations where direct access to the cargo is possible and where the cargo on fire can be submerged with water, large quantities of water may significantly reduce the thermal reactivity and stop the fire.","THE DANGER OF UNCONTROLLED SPREAD OF FIRE SHOULD BE CONSIDERED."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["DO NOT use water or foam; smother with dry inert powdered material when available or let fire burn.","Cool nearby cargo with copious quantities of water."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Let the fire burn. Cool nearby cargo with copious quantities of water. Use the water shield function of portable water monitors when available, to prevent the spread of fire.","Try to avoid getting water into the cargo transport unit on fire."]},{"l":[["Cargo on fire under deck",""]],"p":["Stop ventilation and close hatches.","The fixed gas fire-extinguishing system should be used.","If this is not available:","DO NOT use water onto the material in enclosed spaces under deck. Cool nearby cargo with copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in the fire. Otherwise cool the cargo with copious quantities of water. Use the water shield function of portable water monitors when available, to prevent the spread of fire."]}],"pag":31,"sc":[{"c":"Class 4.3, packing group I","un":[],"p":["In contact with water, large volumes of flammable gases are produced, which when not instantly ignited may form a highly dangerous explosive atmosphere."]}]},"F-H":{"t":"OXIDIZING SUBSTANCES WITH EXPLOSIVE POTENTIAL","r":[{"l":[["General comments",""]],"p":["In a fire, exposed cargoes may explode or their containment may rupture.","Crew members should be aware of the explosion hazard and take appropriate action.","Fight fire from a protected position from as far away as possible.","SUDDEN OR SHORT-TERM EVENTS (e.g. EXPLOSIONS) MAY ENDANGER THE SAFETY OF THE SHIP."]},{"l":[["Cargo on fire on deck","Packages"],["Cargo on fire on deck","Cargo transport units"]],"p":["Create water spray from as many hoses as possible."]},{"l":[["Cargo on fire under deck",""]],"p":["OPEN HATCHES to provide maximum ventilation.","Fixed gas fire-extinguishing systems may not be effective on these fires.","Create water spray from as many hoses as possible."]},{"l":[["Cargo exposed to fire",""]],"p":["Do not move packages that have been exposed to heat.","If practicable, remove or jettison packages which are likely to be involved in the fire. If the packages are not directly involved in the fire, efforts should be concentrated on preventing the fire from reaching the cargo. This is done by keeping the packages wet by using water jets from as far away as practicable to drive the fire away. If the fire reaches the cargo, the firefighters should withdraw to a safe area and continue to fight the fire from a safe position.","Where practicable, articles having been exposed to the fire should be kept separated from unexposed articles. They should be kept wet and monitored from a safe distance."]}],"pag":33,"sc":[]},"F-I":{"t":"RADIOACTIVE MATERIAL","r":[{"l":[["General comments",""]],"p":["Evacuate compartment or downwind area of non-essential personnel.","Do not touch damaged packages.","In cases of suspected radioactive contamination, limit entry of firefighters for the shortest time possible.","For ships carrying radiation monitoring equipment, measure radiation levels.","Radio for expert ADVICE.","After the fire has been extinguished, clean ship’s surfaces with copious quantities of water.","Decontaminate firefighters before protective clothing is removed. Isolate potentially contaminated clothing and equipment.","If exposure of personnel is suspected, clean body and hair with warm water and soap; discharge resultant washings directly overboard.","Record the names of potentially exposed persons. Ensure medical examination of these persons after reaching any medical staff.","For ships carrying radiation monitoring equipment, continue monitoring of radiation levels after fire is extinguished."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["Create water spray from as many hoses as possible."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Create water spray from as many hoses as possible.","Cool burning transport units and nearby cargo exposed to the fire with copious quantities of water."]},{"l":[["Cargo on fire under deck",""]],"p":["Stop ventilation and close hatches.","Use cargo space fixed fire-extinguishing system. If this is not available, create water spray using copious quantities of water."]},{"l":[["Cargo exposed to fire",""]],"p":["If practicable, remove or jettison packages which are likely to be involved in the fire. Otherwise, cool for several hours using copious quantities of water."]}],"pag":34,"sc":[{"c":"","un":["2977","2978","3507"],"p":["Chemical hazard greatly exceeds radiation hazard. Material reacts with moisture to form toxic and corrosive gas. The run-off may be corrosive. Keep clear.","Exposed cargoes may explode in a fire. Create water spray.","Leak may be evident by visible and irritating vapours. Released vapours may also react violently with hydrocarbons (fuel)."]},{"c":"","un":["3332","3333"],"p":["If the source capsule is identified as being out of its packaging, do not touch. Stay away, minimize exposure to radiation by limiting time near material and by maximizing distance. Radio for expert ADVICE."]},{"c":"Subsidiary hazard label class 4.2 or class 4.3","un":[],"p":["All radioactive material with subsidiary hazard label 4.2 or 4.3 affixed (e.g. pyrophoric uranium or thorium metal):","Radio for expert ADVICE.","On deck: Do not use water onto the material. Cool nearby cargo with copious quantities of water, although the fire could intensify for a short period. Do not spray small quantities of water onto the fire, use copious quantities of water.","Under deck: Stop ventilation and close hatches.","The fixed gas fire-extinguishing system should be used.","If this is not available, do not use water onto the material in enclosed spaces under deck. With open hatches, cool nearby cargo with copious quantities of water, although the fire could intensify for a short period. Do not spray small quantities of water onto the fire, use copious quantities of water only."]}]},"F-J":{"t":"NON-TEMPERATURE-CONTROLLED SELF-REACTIVES AND ORGANIC PEROXIDES","r":[{"l":[["General comments",""]],"p":["Exposed cargoes may decompose violently.","Crew members should be aware of the explosion hazard and take appropriate action.","Fight fire from a protected position from as far away as possible.","Exposed cargoes may decompose violently in a fire."]},{"l":[["Cargo on fire on deck","Packages"]],"p":["Not applicable."]},{"l":[["Cargo on fire on deck","Cargo transport units"]],"p":["Cool burning transport units and nearby cargo exposed to the fire with copious quantities of water.","After the fire has been extinguished, carry on water spraying of the container for several hours. Do not open container until well after smoke evolution has ceased. After this, cool down packages, or IBCs if practicable for at least one hour with water. Otherwise, check contents on regular intervals. In case smoke is evolved again, apply further water cooling. Dispose of residues overboard. Clean the area thoroughly.","After the fire has been extinguished, keep cargo transport unit under surveillance."]},{"l":[["Cargo on fire under deck",""]],"p":["Not applicable – According to the IMDG Code, under deck stowage is not allowed. Radio for expert ADVICE."]},{"l":[["Cargo exposed to fire","Cargo transport units with IBCs, packages"]],"p":["Cool unit exposed to the fire with water.","After the fire has been extinguished, keep transport unit under surveillance.","In case of smoke evolution, follow the relevant instructions."]},{"l":[["Cargo exposed to fire","Tanks"]],"p":["Keep personnel away from tank, as fluid ejection from relief arrangements might take place.","Cool unit exposed to the fire with water.","Contact the manufacturer (consignor) of the cargo.","Cooling the tank should be continued until the temperature is below 50°C.","Check temperature frequently. If temperature increases again, cool unit with water.","Consider emptying the tank overboard via bottom outlet, using a flexible hose."]},{"l":[["Smoke evolution","Cargo transport units with IBCs, packages"]],"p":["Cool unit with water.","Use water spray from a protected position.","Do not open the unit until well after smoke evolution has ceased. After this, cool down packages, or IBCs if practicable for at least one hour with water. Otherwise, check contents on regular intervals. In case smoke is evolved again, apply further water cooling. Dispose of residues overboard. Clean the area thoroughly."]},{"l":[["Smoke evolution","Tanks"]],"p":["Keep personnel away from the tank, as fluid ejection from relief arrangements might take place.","Cool unit exposed to fire with water.","Use water spray from a protected position.","Even when smoke evolution or pressure-relief venting has ceased, cooling the tank should be continued until the temperature is below 50°C. Check temperature frequently. If temperature increases again, cool unit with water.","Consider emptying tank overboard via bottom outlet, using a flexible hose."]}],"pag":36,"sc":[]},"S-A":{"t":"TOXIC SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid contact, even when wearing protective clothing.","Stop leak if practicable.","Contaminated clothing should be washed off with water and then removed."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind.","Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate. Keep clear.","Liquids: Provide good ventilation of the space. Restrict flow of liquid to an enclosed area (e.g. by barricading with inert material or cement if available).","Solids: Collect spillage. Dispose of overboard.","Otherwise, keep clear. Radio for expert ADVICE."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Keep clear. Radio for expert ADVICE. After hazard evaluation by experts, you may proceed.","Provide adequate ventilation. Do not enter space without self-contained breathing apparatus.","Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapour evaporate, keep clear. Where the ventilation system is used, particular attention should be taken to prevent toxic vapours or fumes entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Liquids: Provide good ventilation of the space. Wash down to the bottom of the hold. Pump overboard.","Solids: Collect spillage. Keep spilt solids dry and cover with plastic sheet. Dispose of overboard. Otherwise, close hatches. Wait until the ship arrives in port."]}],"pag":49,"sc":[{"c":"Marine pollutant mark","un":[],"p":["Keep disposal overboard as low as possible. Dilute with copious quantities of water. Report incident according to MARPOL reporting requirements."]},{"c":"","un":["3546"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-B":{"t":"CORROSIVE SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid contact, even when wearing protective clothing.","Keep clear of effluent. Keep clear of evolving vapours.","Even short-time inhalation of small quantities of vapour can cause breathing difficulties.","Use of water on the substance may cause a violent reaction and produce toxic vapours.","Substance may damage ship’s construction materials.","Contaminated clothing should be washed off with water and then removed."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive or toxic vapours by using water spray to drive vapours away.","Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapour evaporate. Keep clear.","Liquids: Provide good ventilation of the space. Wash down to the bottom of the hold. Use copious quantities of water. Pump overboard.","Solids: Collect spillage. Dispose of overboard. Wash residues down to the bottom of the hold. Use copious quantities of water. Pump overboard."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive or toxic vapours by using water spray to drive vapours away.","Do not enter space. Keep clear. Radio for expert ADVICE. After hazard evaluation by experts, you may proceed.","Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate, keep clear. Where a ventilation system is used, particular attention should be taken in order to prevent toxic vapours or fumes entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Liquids: Provide good ventilation of the space. Wash down to the bottom of the hold. Use copious quantities of water. Pump overboard.","Solids: Collect spillage. Dispose of overboard. Wash residues down to the bottom of the hold. Use copious quantities of water. Pump overboard."]}],"pag":51,"sc":[{"c":"Marine pollutant mark","un":[],"p":["Report incident according to MARPOL reporting requirements."]},{"c":"","un":["2802","2809","3506"],"p":["No reaction with water. Not highly corrosive to protective clothing. Collect spillages if practicable. Try to avoid disposal overboard. Radio for expert ADVICE."]},{"c":"","un":["3554","3547"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."],"amb":1}]},"S-C":{"t":"FLAMMABLE, CORROSIVE LIQUIDS","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid contact, even when wearing protective clothing.","Keep clear of effluent. Keep clear of evolving vapours.","Even short-time inhalation of small quantities of vapour can cause breathing difficulties.","Use of water on the substance may cause violent reaction and produce toxic vapours.","Substance may damage the ship’s construction materials.","Spillage or reaction with water may evolve flammable vapours. Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction).","Contaminated clothing must be washed off with water and then removed."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash overboard with copious quantities of water. Do not direct water jets straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive or toxic vapours by using water spray to drive vapours away.","Wash overboard with copious quantities of water. Do not direct water jets straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Provide adequate ventilation. Do not enter deck without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate, keep clear.","Liquids: Provide good ventilation of the space. Use water spray on effluent in hold to avoid ignition of flammable vapours. Wash down to the bottom of the hold. Use copious quantities of water. Pump overboard.","Solids: Collect spillage. Dispose of overboard. Wash residues down to the bottom of the hold. Use copious quantities of water. Pump overboard."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive or toxic vapours by using water spray to drive vapours away.","Do not enter space. Keep clear. Radio for expert ADVICE. After hazard evaluation by experts, you may proceed.","Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate, keep clear. Where a ventilation system is used, particular attention should be taken in order to prevent toxic vapours or fumes entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Liquids: Provide good ventilation of the space. Use water spray on effluent to avoid ignition of flammable vapours. Wash down to the bottom of the hold. Use copious quantities of water. Pump overboard.","Solids: Collect spillage. Dispose of overboard. Wash residues down to the bottom of the hold. Use copious quantities of water. Pump overboard."]}],"pag":53,"sc":[{"c":"Marine pollutant mark","un":[],"p":["Report incident according to MARPOL reporting requirements."]},{"c":"","un":["2029","3484"],"p":["Self-ignition of spilt material is possible."]}]},"S-D":{"t":"FLAMMABLE LIQUIDS","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction).","Stop leak if practicable.","Avoid contact, even when wearing protective clothing.","Spillage may evolve flammable vapours.","Contaminated clothing must be washed off with water and then removed."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind.","Wash overboard with copious quantities of water. Do not direct water jet straight onto the spillage. Keep clear of effluent. Clean the area thoroughly."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Shut off all possible sources of ignition in the space. Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If the atmosphere cannot be checked, do not enter. Let vapours evaporate, keep clear.","Provide good ventilation of the space. Use water spray on effluent in hold to avoid ignition of flammable vapours. Wash down to the bottom of the hold. Pump overboard."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive or toxic vapours by using water spray to drive vapours away.","Do not enter space. Keep clear. Radio for expert ADVICE. After hazard evaluation by experts, you may proceed.","Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapour evaporate, keep clear. Where a ventilation system is used, particular attention should be taken in order to prevent toxic vapours or","fumes entering occupied areas of the vessel, e.g. living quarters, machinery spaces, working areas.","Provide good ventilation of the space. Use water spray on effluent in the space to avoid ignition of flammable vapours. Wash down to the bottom of the hold. Use copious quantities of water. Pump overboard."]}],"pag":55,"sc":[{"c":"Marine pollutant mark","un":[],"p":["Report incident according to MARPOL reporting requirements."]},{"c":"","un":["2749"],"p":["Self-ignition of spilt material is possible."]},{"c":"","un":["3359"],"p":["This is a cargo transport unit under fumigation. When opened, it will be ventilated. However, experience has shown that toxic fumigants will stay within packaging material and in non-ventilated areas. Obtain information about the fumigation agent."]},{"c":"","un":["3540"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected and repacked."]}]},"S-E":{"t":"FLAMMABLE LIQUIDS, FLOATING ON WATER","r":[{"l":[["General comments",""]],"p":["Avoid sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools). Liquid is flammable and spillage may evolve flammable vapours.","Wear suitable protective clothing and self-contained breathing apparatus.","Stop leak if practicable.","In general, substances covered under this schedule will have fuel-oil-like properties. They are immiscible with water and are liable to float on the surface of water. The use of inert absorbent material, as used in machinery spaces, is appropriate in all cases. For sticky liquids, shovels may be used, preferably shovels made of non-sparking or non-ferrous material.","You may use light oil or soap-like products (surfactants) to clean small areas. Clean the area thoroughly because of the flammability hazard.","Any pumping of spilled liquid overboard will create an oil spill on the sea surface. In this case, contact coastal authorities.","Report discharges overboard according to MARPOL reporting requirements."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Collect spillage in oil drums, metal boxes, or salvage packagings. You may use inert absorbent material."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Restrict flow of leakage to an enclosed area (e.g. by diking with inert material or cement).","Collect spillage in oil drums, metal boxes, or salvage packagings. You may use inert absorbent material.","Otherwise, wash overboard with copious quantities of water."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Shut off possible sources of ignition in the space. Provide adequate ventilation. Do not enter space without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate.","Collect spillage in oil drums, metal boxes, or salvage packagings. You may use inert absorbent material. Keep collected spillages in well ventilated areas or on deck only."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Shut off possible sources of ignition in the space. Provide adequate ventilation. Do not enter deck without self-contained breathing apparatus. Check atmosphere before entering (toxicity and explosion hazard). If atmosphere cannot be checked, do not enter. Let vapours evaporate. Where a ventilation system is used, particular attention should be taken in order to prevent toxic vapours or fumes entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Provide good ventilation of the space. Use water spray on effluent in the space to avoid ignition of flammable vapours. Wash down to the bottom of the hold. Use copious quantities of water.","Treat effluent according to Shipboard Oil Pollution Emergency Plan. Otherwise, radio for expert ADVICE."]}],"pag":57,"sc":[{"c":"","un":["1136","1993"],"p":["These substances may be miscible with water and hence not float on the surface. In this case, SPILLAGE SCHEDULE S–D will be appropriate."]},{"c":"","un":["1139","1263","1866"],"p":["No thorough cleaning of spillage site necessary. Residues will dry out and coat surfaces."]}]},"S-F":{"t":"WATER-SOLUBLE MARINE POLLUTANTS","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Stop leak if practicable.","Substances covered under this schedule will present a hazard to the marine environment. Try to avoid disposal overboard.","The use of inert absorbent material, as used in machinery spaces, is appropriate in all cases. For sticky liquids, shovels may be used.","Discharge of spilled substance overboard will damage the marine environment, including living resources of the sea. In this case, contact coastal authorities.","Report discharges overboard according to MARPOL reporting requirements."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Liquids: Smother spillage with inert absorbent material.","Collect spillage in oil drums, metal boxes, or salvage packagings.","Solids: Collect material."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Restrict flow of leakage to an enclosed area (e.g. by barricading with inert material or cement if available).","Liquids: Collect spillage in empty tanks, oil drums, metal boxes, or salvage packagings. You may use inert absorbent material.","Solids: Collect spillage in oil drums or metal boxes."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Liquids: Smother spillage with inert absorbent material.","Collect spillage in oil drums, metal boxes, or salvage packagings.","Solids: Collect material."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Restrict flow of leakage to an enclosed area (e.g. by barricading with inert material or cement if available).","Liquids: Collect spillage in empty tanks, oil drums, metal boxes, or salvage packagings. You may use inert absorbent material.","Solids: Collect spillage in oil drums or metal boxes. Otherwise, wash down to the bottom of the hold. Use copious quantities of water. Treat effluent according to Shipboard Oil Pollution Emergency Plan."]}],"pag":59,"sc":[]},"S-G":{"t":"FLAMMABLE SOLIDS AND SELF-REACTIVE SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space without self-contained breathing apparatus.","Check atmosphere before entering (toxicity and explosion hazard).","Collect and contain spillage if practicable. Dispose of overboard.","Collect spillage using soft brushes and plastic trays."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Provide adequate ventilation.","Do not enter space without self-contained breathing apparatus.","Check atmosphere before entering (toxicity and explosion hazard).","Collect and contain spillage if practicable. Dispose of overboard.","Collect spillage using soft brushes and plastic trays."]}],"pag":61,"sc":[{"c":"","un":["3541"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-H":{"t":"FLAMMABLE SOLIDS (MOLTEN MATERIAL)","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable.","Do not touch or walk on spilled material."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"],["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Smother with dry inert material. Dispose of overboard."]}],"pag":62,"sc":[]},"S-I":{"t":"FLAMMABLE SOLIDS (REPACKING POSSIBLE)","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Collect spillage and repack if practicable.","Otherwise, wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Collect spillage and repack if practicable."]}],"pag":63,"sc":[]},"S-J":{"t":"WETTED EXPLOSIVES AND CERTAIN SELF-HEATING SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable.","Dried out material may explode if exposed to heat, flame, friction, or shock."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Keep spillage wet.","Dispose of solid material overboard.","Wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Keep spillage wet.","Collect and contain spillage if practicable. Dispose of overboard.","Collect spillage using soft brushes and plastic trays."]}],"pag":64,"sc":[{"c":"","un":["3542"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-K":{"t":"TEMPERATURE-CONTROLLED SELF-REACTIVE SUBSTANCES","r":[{"l":[["General comments",""]],"p":["If smoke is observed, see FIRE SCHEDULE F-F.","Check temperature reading if possible. If temperature is increasing:","see FIRE SCHEDULE F-F.","Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent.","Leave units closed."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Not applicable. According to the IMDG Code, under deck stowage not allowed. Radio for expert ADVICE."]}],"pag":65,"sc":[]},"S-L":{"t":"SPONTANEOUSLY COMBUSTIBLE, WATER-REACTIVE SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","DO NOT USE WATER."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Avoid getting water on spilled substances or inside cargo transport units.","Smother with dry inert material. Dispose of overboard immediately."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Not applicable. According to the IMDG Code, under deck stowage not allowed. Radio for expert ADVICE."]}],"pag":66,"sc":[{"c":"","un":["2210","2968"],"p":["These substances are allowed to be carried under deck. Take action as given for on deck stowage."]}]},"S-M":{"t":"HAZARD OF SPONTANEOUS IGNITION","r":[{"l":[["General comments",""],["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"],["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Substances covered by this schedule may ignite within 5 minutes after contact with air.","See firefighting guidance: FIRE SCHEDULE F–G."]}],"pag":67,"sc":[{"c":"","un":["3542"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-N":{"t":"SUBSTANCES REACTING VIGOROUSLY WITH WATER","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["If dry, contain and collect spillage if practicable. Dispose of overboard.","Avoid contact with water except to wash residues overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Provide adequate ventilation.","Check atmosphere before entering space (toxicity and explosion hazards). If atmosphere cannot be checked, do not enter. Do not enter space without self-contained breathing apparatus.","Keep dry. Collect spillages using soft brushes and plastic trays.","If dry, collect and contain spillage if practicable. Dispose of overboard.","If wet, use inert absorbent material. Do not use combustible material. Dispose of overboard."]}],"pag":68,"sc":[{"c":"","un":["3543"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-O":{"t":"SUBSTANCES DANGEROUS WHEN WET (NON-COLLECTABLE ARTICLES)","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space without self-contained breathing apparatus.","If dry, collect and contain spillage if practicable. Keep dry. Dispose of overboard. Avoid contact with water except to wash residues with copious quantities of water. Keep clear of effluent.","If wet, wash down to the bottom of the hold. Use copious quantities of water. Pump overboard. If gas is developing, provide good ventilation of the hold. Use water spray on effluent in hold to avoid ignition of flammable vapours."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space without self-contained breathing apparatus.","If dry, collect and contain spillage if practicable. Keep dry. Dispose of overboard. Avoid contact with water except to wash residues with copious quantities of water. Keep clear of effluent.","If wet, wash down to the bottom of the hold. Use copious quantities of water. Pump overboard. If gas is developing, provide good ventilation of the hold. Use water spray on effluent in hold to avoid ignition of flammable vapours. Where a ventilation system is used, particular attention should be taken in order to prevent toxic vapours or fumes entering occupied spaces of the ship, e.g. living quarters, machinery spaces, working areas."]}],"pag":69,"sc":[{"c":"","un":["1295"],"p":["Beware of a highly flammable atmosphere."]}]},"S-P":{"t":"SUBSTANCES DANGEROUS WHEN WET (COLLECTABLE ARTICLES)","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Contain and collect spillage if practicable. Dispose of overboard."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Provide adequate ventilation.","Do not enter space without self-contained breathing apparatus.","Contain and collect spillages if practicable. Dispose of overboard."]}],"pag":70,"sc":[{"c":"","un":["3257","3258"],"p":["Hot substance. No hazard when cool."]},{"c":"","un":["3316"],"p":["If FIRST AID KIT, collect articles and repack."]},{"c":"","un":["3363","3548"],"p":["Substances might be spilled when the articles or machinery are damaged.","Undamaged articles can be collected.","Take care of hazardous properties according to transport documents or radio for expert ADVICE."]}]},"S-Q":{"t":"OXIDIZING SUBSTANCES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","May ignite combustible material (e.g. wood, paper, clothing).","Stop leak if practicable."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space without self-contained breathing apparatus.","If dry, contain and collect spillage if practicable. Dispose of overboard.","If wet, use inert absorbent material. Do not use combustible material.","If liquid, wash down to the bottom of the hold, using copious quantities of water. Pump overboard.","Dispose of overboard."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Provide adequate ventilation.","Do not enter space without self-contained breathing apparatus.","If dry, contain and collect spillage if practicable. Dispose of overboard.","If wet, use inert absorbent material. Do not use combustible material.","If liquid, wash down to the bottom of the hold, using copious quantities of water. Pump overboard.","Dispose of overboard."]}],"pag":71,"sc":[{"c":"","un":["3544"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-R":{"t":"ORGANIC PEROXIDES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Contact of substance (or vapour) with eyes may cause blindness within minutes.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Stop leak if practicable.","Substances covered by this schedule are liable to explode by exposure to heat or ignition.","In case of smoke evolution, see appropriate FIRE SCHEDULE.","Radio for expert ADVICE or contact manufacturer."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Wash overboard with copious quantities of water. Keep clear of effluent.","Collect damaged or leaking receptacles and dispose of overboard.","Handle with care."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Not applicable. According to the IMDG Code, under deck stowage not allowed. Radio for expert ADVICE."]}],"pag":73,"sc":[{"c":"","un":["3545"],"p":["Substances might be spilled when the articles are damaged.","Undamaged articles can be collected."]}]},"S-S":{"t":"RADIOACTIVE MATERIAL","r":[{"l":[["General comments",""]],"p":["Evacuate compartment or downwind area of non-essential personnel.","Provide respiratory protection to personnel in downwind area.","For ships carrying radiation monitoring equipment, measure radiation levels. In this case, assess the extent of contamination and resultant radiation level of the package, the adjacent areas and, if necessary, all other material which has been carried in the conveyance.","Define a zone for restricted entry. Personnel should not enter this zone without suitable protective clothing and self-contained breathing apparatus.","Limit entry of personnel to the restricted zone for the shortest time possible.","Cover liquid spill with inert absorbent materials, if available. Cover powder spills with plastic sheet or tarpaulin to minimize spread.","If exposure of personnel is suspected, clean body and hair with warm water and soap; discharge resultant washings directly overboard.","Record the names of potentially exposed persons. Ensure medical examination of these persons after reaching any medical staff.","Emergency procedures, if established for the ship or the specific cargo by relevant authorities or the shipper, should be followed.","For ships carrying radiation monitoring equipment, continue monitoring the radiation levels.","Radio for expert ADVICE."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Wash spillages overboard with copious quantities of water. Keep clear of effluent.","Packages damaged or leaking radioactive contents may be removed to an acceptable restricted access interim location. Isolate and sheet over. Do not remove packages from restricted access zone until approved by the competent authority."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Let released gas escape. Keep clear. Use water spray to protect bridge, living quarters and personnel from precipitation of vapours (water curtain).","Absorb liquid spillage, where practicable, using absorbent material. Isolate and sheet over.","Packages damaged or leaking radioactive contents may be removed to an acceptable restricted access interim location. Isolate and sheet over. Do not remove packages from restricted access zone until approved by the competent authority.","Wash residues of liquids or solids overboard with copious quantities of water (use spray nozzles). Do not allow water to enter receptacles."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Provide adequate ventilation.","Let released gas escape, keep clear. Where a ventilation system is used, particular attention should be taken in order to prevent radioactive vapours or fumes entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Keep solids dry.","Absorb liquid spillage, where practicable, using inert absorbent material. Isolate and sheet over.","Packages damaged or leaking radioactive contents may be removed to an acceptable restricted access interim location. Isolate and sheet over. Do not remove packages from restricted access zone until approved by the competent authority.","Keep working period of emergency team in space as short as possible."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space. Radio for expert ADVICE.","If liquid, or vapour is developing: Where a ventilation system is used, particular attention should be taken in order to prevent radioactive vapours entering occupied areas of the ship, e.g. living quarters, machinery spaces, working areas. Use water spray to protect bridge, living quarters and personnel from precipitation of vapours evolving from the hold (water curtain)."]},{"l":[["Restowing of packages UN 2977, UN 3324, UN 3325, UN 3326, UN 3327, UN 3328, UN 3329, UN 3330, UN 3331",""]],"p":["Check package labels and transport documents to determine whether packages contain fissile material.","Prior to any restowing of these packages, radio for expert ADVICE."]}],"pag":74,"sc":[{"c":"","un":["2977","2978","3507"],"p":["Avoid contact, even when wearing protective clothing. Keep clear of evolving vapours. Even short-time inhalation of small quantities of vapour can cause breathing difficulties.","Bear in mind that gases are heavier than air. Measures should be taken to prevent leaking gases from penetrating into any other part of the ship.","Keep bridge and living quarters upwind. Protect crew and living quarters against corrosive and toxic vapours by using water spray to drive vapours away.","Do not enter space without protective equipment. Keep clear. Radio for expert ADVICE."]},{"c":"","un":["3332","3333"],"p":["If a special form radioactive material is identified as being outside its packaging, do not touch. Stay away and radio for expert ADVICE."]},{"c":"","un":["2919","3331"],"p":["For radioactive material, transported under special arrangement, use special precautions, operational controls or emergency procedures as specifically designated by the competent authorities in their approval certificates and declared by the shipper in its transport documents."]},{"c":"Subsidiary hazard labels class 4.2 or class 4.3","un":[],"p":["These are pyrophoric substances; water will ignite the material. DO NOT USE WATER. Radio for expert ADVICE."]}]},"S-T":{"t":"DANGEROUS GOODS WITH BIOHAZARD","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Avoid handling leaking or damaged packages or keep handling to a minimum.","Inform the public health, veterinary or other competent authority if persons or the marine environment might have been exposed. A competent authority to which actual or suspected leakage is reported should notify the authorities of any countries in which the goods may have been handled, including countries of transit.","Radio for expert ADVICE.","Notify consignor/consignee."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Stop leak if practicable.","Collect potentially contaminated packages or equipment. Isolate and sheet over.","Wash spillage or residues overboard with copious quantities of water. Keep clear of effluent.","Clean contaminated area thoroughly using bleach-like products (like sodium hypochlorite 1–6% solution or Javel water). Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space."]}],"pag":77,"sc":[]},"S-U":{"t":"GASES (FLAMMABLE, TOXIC OR CORROSIVE)","r":[{"l":[["General comments",""]],"p":["Spaces and areas where leakages or spillages have occurred should be evacuated downwind immediately.","Take care: Flames may be invisible. Leaking gas may be extremely cold.","Measures should be taken to prevent leaking gases from penetrating into any other part of the ship. Bear in mind that some gases are heavier than air or may otherwise accumulate in lower or non-ventilated parts of the ship. Ensure that there is no smoking or any other open fire on board unless the leak has been closed and all spaces have been ventilated. Particular attention should be taken in order to prevent gases drifting into occupied areas of the ship, e.g. living quarters, machinery spaces, working areas.","Wear protective clothing suitable for gas protection and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Even short inhalation of small quantities of gas can cause breathing difficulties. Keep clear of evolving gases. Avoid all skin contact.","Let spilt liquefied gas evaporate. When in contact with cold liquefied gases, most materials become brittle and are likely to break without warning. Avoid all contact, even when wearing protective clothing. If practicable, protect ship’s superstructure with copious quantities of water. Do not direct water jet onto the spill."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Let gas dissipate. Keep clear."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Let gas dissipate. Keep bridge and living quarters upwind.","Otherwise, protect crew and living quarters against flammable or toxic gases by using water spray to drive gases away (water curtain).","Spilt liquefied gas: Use water jets from as far as practicable to accelerate evaporation, not directing them straight onto the spill."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space. Provide adequate ventilation.","Where a ventilation system is used, particular attention should be taken in order to prevent gases penetrating into other areas of the ship.","Let gas evaporate. Keep clear. Radio for expert ADVICE.","Check atmosphere before entering (toxicity and explosion hazard). Do not enter space without self-contained breathing apparatus."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space. Provide adequate ventilation.","Where a ventilation system is used, particular attention should be taken in order to prevent gases drifting into other areas of the ship.","Keep bridge and living quarters upwind.","Otherwise, protect crew and living quarters against flammable or toxic gases by using water spray to drive gases away (water curtain).","If practicable, use water spray to avoid ignition of flammable gases in the space.","Radio for expert ADVICE.","Check atmosphere before entering (toxicity and explosion hazard).","Do not enter deck without self-contained breathing apparatus."]}],"pag":78,"sc":[{"c":"","un":["1001","3374"],"p":["Heated or roughly handled receptacles may explode even after several hours of being removed from external sources of heat. Cool for several hours by using water."]},{"c":"","un":["1614"],"p":["The gas is absorbed in a porous inert material but will evaporate if the receptacle is damaged."]},{"c":"","un":["3501"],"p":["A flammable liquid, paste or powder may be expelled if the package is ruptured. Also consult SPILLAGE SCHEDULES S-D or S-G, as appropriate."]},{"c":"","un":["3504"],"p":["A flammable or toxic liquid, paste or powder may be expelled if the package is ruptured. Also consult SPILLAGE SCHEDULES S-D, S-G or S-A, as appropriate."]},{"c":"","un":["3505"],"p":["A flammable or corrosive liquid, paste or powder may be expelled if the package is ruptured. Also consult SPILLAGE SCHEDULES S-C or S-G, as appropriate."]},{"c":"","un":["3537","3539"],"p":["Gases might be released when the articles are damaged.","Undamaged articles can be collected and repacked."]}]},"S-V":{"t":"GASES (NON-FLAMMABLE, NON-TOXIC)","r":[{"l":[["General comments",""]],"p":["Measures should be taken to prevent leaking gases from penetrating into any other part of the ship. Bear in mind that some gases are heavier than air or may otherwise accumulate in lower or non-ventilated parts of the ship. Particular attention should be taken in order to prevent gases drifting into occupied areas of the ship, e.g. living quarters, machinery spaces, working areas. Leaking gas may be extremely cold.","Wear suitable protective clothing and self-contained breathing apparatus (suffocation hazard).","Let spilt liquefied gas evaporate. When in contact with cold liquefied gases, most materials become brittle and are likely to break without warning. Avoid all contact, even when wearing protective clothing. If practicable, protect ship’s superstructure with copious quantities of water. Do not direct water jet onto the spill."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Let gas dissipate. Keep clear."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Let gas dissipate.","Spilt liquefied gas: Use water jets from as far as practicable to accelerate evaporation, not directing them straight onto the spill.","Keep clear of evolving gases."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Provide adequate ventilation.","Stop leak if practicable. Otherwise, let gas evaporate. Keep clear.","Check atmosphere before entering space (suffocation hazard). Do not enter space without self-contained breathing apparatus."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Provide adequate ventilation.","Stop leak if practicable. Otherwise, let gas evaporate. Keep clear.","Spilt liquefied gas: Use water jets from as far as practicable to accelerate evaporation, not directing them straight onto the spill.","Check atmosphere before entering space (suffocation hazard). Do not enter space without self-contained breathing apparatus."]}],"pag":81,"sc":[{"c":"","un":["2990","3072"],"p":["No suffocation hazard. Collect articles and repack."]},{"c":"","un":["3502"],"p":["A toxic liquid, paste or powder may be expelled if the package is ruptured. Also consult SPILLAGE SCHEDULE S-A."]},{"c":"","un":["3503"],"p":["A corrosive liquid, paste or powder may be expelled if the package is ruptured. Also consult SPILLAGE SCHEDULES S-C or S-G, as appropriate."]},{"c":"","un":["3538"],"p":["Gases might be released when the articles are damaged.","Undamaged articles can be collected and repacked."]}]},"S-W":{"t":"OXIDIZING GASES","r":[{"l":[["General comments",""]],"p":["Areas containing leakages or spillages should be evacuated downwind immediately.","These gases may ignite combustible material and enhance fire.","Take care: Flames may be invisible. Leaking gas may be extremely cold.","Measures should be taken to prevent leaking gases from penetrating into any other part of the ship.","Ensure that there is no smoking or any other open fire on board unless the leak has been closed and all spaces have been ventilated. Particular attention should be taken in order to prevent gases drifting into occupied areas of the vessel, e.g. living quarters, machinery spaces, working areas.","Wear suitable protective clothing and self-contained breathing apparatus.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools, friction). Wear non-sparking footwear.","Even short inhalation of small quantities of gas can cause breathing difficulties. Keep clear of evolving gases. Avoid all skin contact.","Let spilt liquefied gas evaporate. When in contact with cold liquefied gases, most materials become brittle and are likely to break without warning. Avoid all contact, even when wearing protective clothing. If practicable, protect ship’s superstructure with copious quantities of water. Do not direct water jet onto the spill."]},{"l":[["Spillage on deck","Packages (small spillage)"]],"p":["Let gas evaporate. Keep clear."]},{"l":[["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Let gas evaporate.","Keep bridge and living quarters upwind.","Otherwise, protect crew and living quarters against flammable or toxic gases by using water spray to drive gases away (water curtain).","Spilt liquefied gas: Use water jets from as far as practicable to accelerate evaporation, not directing them straight onto the spill."]},{"l":[["Spillage under deck","Packages (small spillage)"]],"p":["Do not enter space.","Provide adequate ventilation.","Where a ventilation system is used, particular attention should be observed in order to prevent gases penetrating into other areas of the ship.","Let gas evaporate. Keep clear.","Radio for expert ADVICE.","Check atmosphere before entering space (toxicity and explosion hazard). Do not enter space without self-contained breathing apparatus."]},{"l":[["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space.","Provide adequate ventilation.","Where a ventilation system is used, particular attention should be observed in order to prevent gases drifting into other areas of the ship.","Keep bridge and living quarters upwind.","Otherwise, protect crew and living quarters against gases by using water spray to drive gases away (water curtain).","If practicable, use water spray to avoid ignition of gases in the space.","Radio for expert ADVICE."]}],"pag":83,"sc":[{"c":"","un":["1072","1073"],"p":["This is concentrated oxygen. No inhalation hazard after a short distance from a leak.","No skin irritation hazard."]}]},"S-X":{"t":"EXPLOSIVE ITEMS AND ARTICLES","r":[{"l":[["General comments",""]],"p":["Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools).","Electrostatic hazard: Electric charge may ignite ammunition. Keep spilled material away from generators of static electricity (e.g. mobile phones, friction of synthetic polymers like PVC gloves). Wear non-sparking footwear."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate out, and radio for expert ADVICE.","Spilled substance: Keep wet. Wash spillage overboard with copious quantities of water."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate and radio for expert ADVICE.","Spilled substance: Keep wet. Collect spillage where practicable. Dispose of overboard."]}],"pag":85,"sc":[]},"S-Y":{"t":"EXPLOSIVE CHEMICALS","r":[{"l":[["General comments",""]],"p":["Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools).","Stop leak if practicable.","Electrostatic hazard: Electric charge may ignite ammunition. Keep spilled material away from generators of static electricity (e.g. mobile phones, friction of synthetic polymers like PVC gloves). Wear non-sparking footwear.","Some explosive mixtures are stabilized in such a way that water will separate explosives from the stabilizer, thus creating a higher risk. The explosive component becomes very sensitive to shock and heat.","Radio for expert ADVICE."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate out, and ask for expert ADVICE. Wetted articles should be jettisoned.","Spilled substance: Keep it under water. Wash spillages overboard with copious quantities of water."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate out, and radio for expert ADVICE. Wetted articles should be jettisoned.","Spilled substance: Keep it under water. Collect spillages where practicable. Dispose of overboard."]}],"pag":86,"sc":[]},"S-Z":{"t":"TOXIC EXPLOSIVES","r":[{"l":[["General comments",""]],"p":["Wear suitable protective clothing and self-contained breathing apparatus.","Even short inhalation of small quantities of gas can cause breathing difficulties or lead to severe poisoning.","Avoid all sources of ignition (e.g. naked lights, unprotected light bulbs, electric handtools).","Electrostatic hazard: Electric charge may ignite ammunition. Keep spilled material away from generators of static electricity (e.g. mobile phones, friction of synthetic polymers like PVC gloves). Wear non-sparking footwear.","Particular attention should be taken in order to prevent developing gases drifting into occupied areas of the ship, e.g. living quarters, machinery, working areas.","Keep bridge and living quarters upwind. Otherwise, protect crew and living quarters against gases by using water spray to drive gases away (water curtain).","Radio for expert ADVICE."]},{"l":[["Spillage on deck","Packages (small spillage)"],["Spillage on deck","Cargo transport units (large spillage)"]],"p":["Let vapours dissipate, keep clear.","Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate out, and ask for expert ADVICE.","Spilled substance: Keep wet. Wash spillage overboard with copious quantities of water. Keep clear of effluent."]},{"l":[["Spillage under deck","Packages (small spillage)"],["Spillage under deck","Cargo transport units (large spillage)"]],"p":["Do not enter space without self-contained breathing apparatus. Check atmosphere before entering. Let vapours dissipate, keep clear.","Articles: Sweep or pick up articles. If the articles remain intact but appear damaged, separate out, and ask for expert ADVICE.","Spilled substance: Keep wet. Collect spillages where practicable. Dispose of overboard."]}],"pag":87,"sc":[]}},"ordine":["F-A","F-B","F-C","F-D","F-E","F-F","F-G","F-H","F-I","F-J","S-A","S-B","S-C","S-D","S-E","S-F","S-G","S-H","S-I","S-J","S-K","S-L","S-M","S-N","S-O","S-P","S-Q","S-R","S-S","S-T","S-U","S-V","S-W","S-X","S-Y","S-Z"],"lg":{"F":{"punti":["Think safety first!","Avoid any contact with dangerous substances.","Keep away from fire, smoke, fumes, and vapours.","Sound the fire alarm and start firefighting procedures.","Keep the bridge and living quarters upwind if possible.","Locate stowage position of cargo that is burning or evolving smoke.","Identify cargo.","Obtain UN numbers and the EmS FIRE SCHEDULE of the dangerous goods involved.","Consider which measures of the EmS FIRE SCHEDULE are applicable and should be followed.","Check if other dangerous goods may potentially be involved in the fire and identify the relevant EmS FIRE SCHEDULE.","Wear suitable protective clothing and self-contained breathing apparatus.","Be prepared to use the Medical First Aid Guide (MFAG).","Contact the designated person of the company responsible for the operation of the ship or a rescue coordination centre to obtain expert advice on dangerous goods emergency response measures."],"prec":"Precaution: Contamination of the skin with dangerous goods should be removed and washed"},"S":{"punti":["Think of safety first!","Avoid any contact with dangerous substances. Do not walk through spilled liquids or dust (solids).","Keep away from vapours or gases.","Sound alarm.","Keep the bridge and living quarters upwind if possible.","Wear full protective clothing resistant to chemical attack and self-contained breathing apparatus.","Locate stowage position of leaking cargo.","Identify cargo.","Obtain UN numbers and the EmS SPILLAGE SCHEDULE of dangerous goods involved.","Consider which measures of the EmS SPILLAGE SCHEDULE are applicable and should be followed.","Be prepared to use the Medical First Aid Guide (MFAG).","Contact the designated person of the company responsible for the operation of the ship to obtain expert advice on dangerous goods emergency response measures."],"prec":"Precaution: Contamination of the skin with any dangerous goods should be removed and"}},"note":{"3166":"Index: F-D, S-U for gases; F-E, S-E for liquids.","3542":"Index: F-G, S-M for pyrophoric substances; F-A, S-J for self-heating substances."}};
